  var SMOKE_SVG = '<svg viewBox="0 0 8 28" aria-hidden="true"><path d="M4 28 C1.5 23 6.5 19.5 4 15 C1.5 10.5 6.5 7 4 1" stroke="#cfc9c2" stroke-width="1.5" fill="none" stroke-linecap="round" opacity=".9"/></svg>';
