        s.innerHTML = SEED_SVG;
        const x0 = fill ? this._x + this._dir * pW * 0.25 : F.left + F.w * pick([0.15, 0.85]) + rnd(-2, 2);
        const y0 = fill ? gy - pH * 0.55 : tray;
