      this._a2RadioPeep(pick(["krrz…", "kschhh…"]));
      await this._wait(900);
      S.el.classList.remove("a2rtune");
      S.on = true;
      S.gold = gold;
      S.el.classList.add("on");
      this._say(pick(RADIO_SENDER[S.st].say), 1300);
